import RNA, random
from multiprocessing import Pool
t='......((.((..((..(...(.((.((....))))..)...(.((..((....))..))..)...).))..)))).....................'

def one(args):
    rng=random.Random(args)
    best=None;bestd=999
    for _ in range(20):
        start=''.join(rng.choice('ACGU') for _ in range(97))
        try:
            seq,_=RNA.inverse_fold(start, t)
        except Exception:
            continue
        fc=RNA.fold_compound(seq)
        mfe,_=fc.mfe()
        d=RNA.bp_distance(mfe,t)
        if d<bestd:
            bestd=d;best=seq
        if d==0:
            return (0,seq)
    return (bestd,best)

if __name__=='__main__':
    with Pool(16) as p:
        results=p.map(one, range(400))
    results=[r for r in results if r[1]]
    results.sort(key=lambda x:x[0])
    print('BEST', results[0], flush=True)
    print('TOP5', results[:5], flush=True)
EOF
